import type { ReactElement } from 'react'
import { useMemo } from 'react'

interface Order { id: number, number: string, total: number }

// Sums the visible orders; amounts stay in minor units until display.
export function OrderTotal({ orders, currency = 'USD' }: { orders: Order[], currency?: string }): ReactElement {
  const sum = useMemo(() => orders.reduce((total, order) => total + order.total, 0), [orders])
  return <strong className="tabular-nums">{(sum / 100).toFixed(2)} {currency}</strong>
}

:root {
  --lumi-theme-brand: #2d5bff;
  --lumi-theme-radius: 0.5rem;
}

/* Totals line up in columns. */
.order-total {
  font-variant-numeric: tabular-nums;
  padding: 0 12px;
}

