package handlers

import (
	"encoding/json"
	"net/http"
)

// ListOrders answers the query the orders page sends on load.
func ListOrders(w http.ResponseWriter, r *http.Request) {
	status := r.URL.Query().Get("status")
	orders, total, err := store.Orders(r.Context(), status)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]any{"data": orders, "meta": map[string]int{"total": total}})
}

